import request from './request'

export const authApi = {
  login: (data) => request.post('/auth/login', data),
  register: (data) => request.post('/auth/register', data),
  getUserInfo: () => request.get('/auth/userinfo'),
  getUsers: () => request.get('/auth/users')
}

export const maintenanceApi = {
  getList: (params) => request.get('/maintenance/list', { params }),
  getDetail: (id) => request.get(`/maintenance/detail/${id}`),
  create: (data) => request.post('/maintenance/create', data),
  update: (id, data) => request.put(`/maintenance/update/${id}`, data),
  delete: (id) => request.delete(`/maintenance/delete/${id}`),
  getByElement: (elementId) => request.get(`/maintenance/by-element/${elementId}`),
  getStatistics: () => request.get('/maintenance/statistics')
}

export const uploadApi = {
  uploadImage: (file) => {
    const formData = new FormData()
    formData.append('file', file)
    return request.post('/upload/image', formData, {
      headers: { 'Content-Type': 'multipart/form-data' }
    })
  },
  uploadImages: (files) => {
    const formData = new FormData()
    files.forEach(f => formData.append('files', f))
    return request.post('/upload/images', formData, {
      headers: { 'Content-Type': 'multipart/form-data' }
    })
  }
}

export const bimApi = {
  getModels: () => request.get('/bim/models'),
  getModel: (token) => request.get(`/bim/model/${token}`),
  getModelViewer: (token) => request.get(`/bim/model/${token}/viewer`),
  getModelTree: (token) => request.get(`/bim/model/${token}/tree`),
  getModelFloors: (token) => request.get(`/bim/model/${token}/floors`),
  getComponent: (token, elementId) => request.get(`/bim/model/${token}/component/${elementId}`),
  getComponentBox: (token, elementId) => request.get(`/bim/model/${token}/component/${elementId}/box`),
  getComponents: (token, elementIds) => request.post(`/bim/model/${token}/components`, { elementIds }),
  setFloorVisibility: (token, floors) => request.post(`/bim/model/${token}/floor/visibility`, { floors }),
  screenshot: (token, options) => request.post(`/bim/model/${token}/screenshot`, options)
}
